class ArtifactReader:
    def __init__(self,path):
        self.path=Path(path);self.z=None;self.prefix=''
        if self.path.is_file():
            self.z=zipfile.ZipFile(self.path)
            matches=[n for n in self.z.namelist() if Path(n).name=='run_status.json']
            if len(matches)!=1:raise RuntimeError('Expected one run_status.json in E01B artifacts ZIP.')
            self.prefix=matches[0][:-len('run_status.json')]
            assert len(set(self.z.namelist()))==len(self.z.namelist()),'Duplicate ZIP members'
    def read(self,n):
        p=Path(n)
        if p.is_absolute() or '..' in p.parts:raise RuntimeError('Invalid relative path')
        return self.z.read(self.prefix+n) if self.z else (self.path/n).read_bytes()
    def obj(self,n):return json.loads(self.read(n))
    def csv(self,n):return frame(self.read(n))
    def arr(self,n):return np.load(io.BytesIO(self.read(n)),allow_pickle=False)

