# Cell 5
def fwht(x):
    out=np.array(x,dtype=float,copy=True); width=out.shape[1]; h=1
    while h<width:
        v=out.reshape(len(out),-1,2*h); a=v[:,:,:h].copy(); b=v[:,:,h:].copy()
        v[:,:,:h]=a+b; v[:,:,h:]=a-b; h*=2
    return out/np.sqrt(width)

def namespace(seed,method):
    if method=='RO':return seed
    return int.from_bytes(hashlib.sha256(f'CFP-E06|{method}|{seed}'.encode()).digest()[:8],'little')

def qr(d,seed):
    q,r=np.linalg.qr(np.random.default_rng(seed).standard_normal((d,d)))
    return np.ascontiguousarray(q*np.where(np.diag(r)<0,-1.,1.))

def conservative_threshold(scores):
    a=np.sort(scores); budget=int(np.floor(TARGET_FAR*len(a)))
    t=float(np.nextafter(a[len(a)-budget-1],np.inf))
    assert np.count_nonzero(a>=t)<=budget
    return t

def balanced_threshold(y,s):
    f,t,th=roc_curve(y,s,drop_intermediate=False)
    ba=(t+1-f)/2; valid=np.isfinite(th)
    best=ba[valid].max()
    return float(th[valid & np.isclose(ba,best,atol=1e-12,rtol=0)].max())

def dsys(y,s):
    # Exact histogram-bin mass sum, avoiding endpoint loss from trapezoid integration.
    g=np.histogram(s[y==1],bins=100,range=(0,1))[0].astype(float);g/=g.sum()
    i=np.histogram(s[y==0],bins=100,range=(0,1))[0].astype(float);i/=i.sum()
    local=np.divide(g-i,g+i,out=np.zeros_like(g),where=(g+i)>0)
    return float(np.sum(g*np.maximum(local,0)))

def hscore(B,a,b):return (B[a]==B[b]).mean(axis=1)

def features(B,query,ex,p,reverse=False):
    a,b=p.a.to_numpy(),p.b.to_numpy()
    if reverse:a,b=b,a
    query_bits=B[query,b]
    agree=np.stack([B[k,a]==query_bits for k in ex],axis=1)
    hs=agree.mean(axis=2)
    return np.column_stack([agree.mean(axis=1),np.sort(hs,axis=1),hs.mean(1),hs.std(1),hs.min(1),hs.max(1),np.median(hs,axis=1),np.ptp(hs,axis=1)])
def unit(x):
    norms=np.linalg.norm(x,axis=1,keepdims=True)
    assert np.isfinite(x).all() and (norms>1e-12).all()
    return x/norms

def templates(enc,seed,method,bits):
    x=Xall[enc];mu,V=PCA[enc,seed];pdim=256 if bits==128 else 512
    z=unit((x-mu)@V[:,:pdim]) if method=='PCA_GUIDED_RO' else None
    result=[]
    for ki,key in enumerate(KEY_SEEDS):
        if method=='RO':
            w=RO[ki,:,:bits];v=x@w;payload=w.tobytes()
        elif method=='SRHT':
            signs=SIGNS[ki];perm=PERMS[ki,:bits];v=fwht(x*signs)[:,perm]
            payload=signs.tobytes()+perm.tobytes()
        else:
            w=qr(pdim,namespace(key,'PCA_GUIDED_RO'))[:,:bits];v=z@w;payload=w.tobytes()
        ref=op_audit[(op_audit.encoder==enc)&(op_audit.split_seed==seed)&(op_audit.method==method)&(op_audit.bits==bits)&(op_audit.key_seed==key)]
        assert len(ref)==1 and sha(payload)==ref.iloc[0].sha256,'Projection changed since E01B'
        result.append(v>=0)
    return np.stack(result)

