def verifier_thresholds(B,enc,seed,method,bits):
    val=pairsets[seed]['validation'];test=pairsets[seed]['test'];vy=val.label.to_numpy();ty=test.label.to_numpy()
    thresholds=[];records=[]
    for ki,key in enumerate(KEY_SEEDS):
        vs=hscore(B[ki],val.a,val.b);ts=hscore(B[ki],test.a,test.b)
        th=conservative_threshold(vs[vy==0]);ref=expected.loc[(enc,seed,method,bits,key)]
        ga=int((ts[ty==1]>=th).sum());fa=int((ts[ty==0]>=th).sum())
        assert th==ref.threshold and ga==ref.genuine_accepts and fa==ref.false_accepts,'E01B utility reproduction failed'
        thresholds.append(th)
        records.append(dict(encoder=enc,split_seed=seed,method=method,bits=bits,key_seed=key,
                            threshold=th,tar=ga/int((ty==1).sum()),far=fa/int((ty==0).sum())))
    return thresholds,records


