def is_done(tag):
    p=OUT/(tag+'.done.json')
    if not p.exists():return False
    record=json.loads(p.read_text())
    assert record['binding']==binding,'Checkpoint binding changed'
    for rel,digest in record['files'].items():
        assert (BASE/rel).is_file() and sha((BASE/rel).read_bytes())==digest,'Corrupt checkpoint; do not skip'
    return True

def mark_done(tag,paths):
    dump(OUT/(tag+'.done.json'),dict(binding=binding,files={p.relative_to(BASE).as_posix():sha(p.read_bytes()) for p in paths}))


