def run_query(B,thresholds,enc,seed,method,bits,q):
    tag=f'{enc}_s{seed}_{method}_b{bits}_q{KEY_SEEDS[q]}'
    if is_done(tag):print('Resume:',tag,flush=True);return
    tr,va,te=[pairsets[seed][p] for p in ['train','validation','test']]
    vy=va.label.to_numpy();ty=te.label.to_numpy();g=te[te.label==1]
    olds=[i for i in range(20) if i!=q];replay=[];masks=[];mask_index=[]
    for old in olds:
        cases=[('same_image',test_rows[seed],test_rows[seed]),
               ('frontal_to_profile',g.a.to_numpy(),g.b.to_numpy()),
               ('profile_to_frontal',g.b.to_numpy(),g.a.to_numpy())]
        for kind,a,b in cases:
            scores=(B[old,a]==B[q,b]).mean(axis=1);accept=scores>=thresholds[q]
            replay.append(dict(encoder=enc,split_seed=seed,method=method,bits=bits,old_seed=KEY_SEEDS[old],
                new_seed=KEY_SEEDS[q],endpoint=kind,threshold=thresholds[q],accepted=int(accept.sum()),
                trials=len(accept),acceptance_rate=float(accept.mean())))
            masks.append(np.packbits(accept,bitorder='big'))
            mask_index.append(dict(old_seed=KEY_SEEDS[old],new_seed=KEY_SEEDS[q],endpoint=kind,trials=len(accept)))
    replay_csv=OUT/(tag+'_replay.csv');pd.DataFrame(replay).to_csv(replay_csv,index=False)
    replay_npz=EVID/(tag+'_replay.npz')
    np.savez_compressed(replay_npz,**{f'mask_{i}':a for i,a in enumerate(masks)},
        same_image_rows=test_rows[seed],genuine_a=g.a.to_numpy(),genuine_b=g.b.to_numpy())
    replay_index=EVID/(tag+'_replay_index.json');dump(replay_index,mask_index)
    exposed=[(q+j)%20 for j in range(1,11)]
    attacks=[];arrays={};index=[]
    for reverse in [False,True]:
        for k in EXPOSURES:
            ex=exposed[:k]
            ftr,fva,fte=[features(B,q,ex,p,reverse) for p in [tr,va,te]]
            model=make_pipeline(StandardScaler(),LogisticRegression(C=1.,solver='liblinear',max_iter=2000,random_state=0,tol=1e-4))
            model.fit(ftr,tr.label)
            vs=model.predict_proba(fva)[:,1];ts=model.predict_proba(fte)[:,1]
            assert np.isfinite(vs).all() and np.isfinite(ts).all()
            th=balanced_threshold(vy,vs);auc=float(roc_auc_score(ty,ts));vauc=float(roc_auc_score(vy,vs))
            base=fte[:,bits:bits+k].mean(1);vbase=fva[:,bits:bits+k].mean(1)
            bau=float(roc_auc_score(ty,base));vbauc=float(roc_auc_score(vy,vbase))
            rec=dict(encoder=enc,split_seed=seed,method=method,bits=bits,query_seed=KEY_SEEDS[q],
                reverse=reverse,K=k,auc=auc,validation_auc=vauc,
                validation_oriented_auc=auc if vauc>=.5 else 1-auc,
                posthoc_direction_aware_auc=max(auc,1-auc),d_sys=dsys(ty,ts),
                balanced_accuracy=float(balanced_accuracy_score(ty,ts>=th)),threshold=th,
                baseline_auc=bau,baseline_validation_oriented_auc=bau if vbauc>=.5 else 1-bau,
                baseline_posthoc_direction_aware_auc=max(bau,1-bau),test_pairs=len(ty),
                train_pairs=len(tr),iterations=int(model[-1].n_iter_[0]))
            attacks.append(rec);i=len(index);index.append(dict(reverse=reverse,K=k,query_seed=KEY_SEEDS[q],exposure_seeds=[KEY_SEEDS[e] for e in ex]))
            arrays.update({f'validation_{i}':vs,f'test_{i}':ts,f'baseline_validation_{i}':vbase,
                           f'baseline_test_{i}':base,f'scaler_mean_{i}':model[0].mean_,
                           f'scaler_scale_{i}':model[0].scale_,f'coef_{i}':model[-1].coef_,f'intercept_{i}':model[-1].intercept_})
    attack_csv=OUT/(tag+'_linkage.csv');pd.DataFrame(attacks).to_csv(attack_csv,index=False)
    score_file=EVID/(tag+'_linkage.npz');np.savez_compressed(score_file,validation_labels=vy,test_labels=ty,**arrays)
    index_file=EVID/(tag+'_linkage_index.json');dump(index_file,index)
    mark_done(tag,[replay_csv,replay_npz,replay_index,attack_csv,score_file,index_file])
    print('Completed:',tag,'| 8 linkage fits | 57 replay conditions',flush=True)

utility=[];block=0;total=len(ENCODERS)*len(SPLIT_SEEDS)*len(METHODS)*len(DIMENSIONS)*len(QUERY_INDICES)
